#include "unity.h"
#include "buffer.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_append_n_enough_space_no_resize(void) {
    // Setup: buffer with enough space for append (self->len > needed)
    // Initial data: "foo", buffer size: 16
    buffer_t *buf = helper_make_buffer_with_size(16);
    TEST_ASSERT_NOT_NULL(buf);
    // Set initial data to "foo"
    strcpy(buf->data, "foo");
    // Append "bar" (len = 3)
    const char *to_append = "bar";
    size_t append_len = 3;

    // Precondition: self->len > needed
    // needed = strlen("foo") + 3 = 3 + 3 = 6; self->len = 16 > 6

    // Test: call buffer_append_n
    int ret = buffer_append_n(buf, to_append, append_len);

    // Assertions
    TEST_ASSERT_EQUAL(0, ret);
    // Buffer data should now be "foobar"
    helper_assert_buffer_data_equals(buf, "foobar");
    // Buffer string length should be 6
    helper_assert_buffer_length(buf, 6);
    // Buffer size should remain unchanged
    helper_assert_buffer_size(buf, 16);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_n_enough_space_no_resize);
    return UNITY_END();
}

